import {
  Mesh,
  MeshBasicNodeMaterial,
  PlaneGeometry,
} from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';

/**
 * Journal card 3 – textured plane with interactive hover lift, press-down click,
 * accent edge on focus, and a stock badge placeholder.
 */
export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  const { paper, accent, surface } = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const imageUrl = config.imageUrl;

  // --- Card dimensions (matching atlas source rect aspect 512:320 ≈ 1.6) ---
  const W = 1.6;
  const H = 1.2;

  // --- Main card plane ---
  const cardGeo = new PlaneGeometry(W, H);
  const cardMat = new MeshBasicNodeMaterial({
    color: surface || '#0b0b10',
    side: ctx.THREE.DoubleSide,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // --- Accent border (slightly larger, hidden by default) ---
  const borderGeo = new PlaneGeometry(W + 0.06, H + 0.06);
  const borderMat = new MeshBasicNodeMaterial({
    color: accent || '#ff2a38',
    side: ctx.THREE.DoubleSide,
    transparent: true,
    opacity: 0,
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.005; // behind card
  group.add(borderMesh);

  // --- Stock badge (placeholder text) ---
  const badgeText = ctx.fontAtlas.createText('In Stock', {
    fontSize: 0.09,
    color: paper || '#e8ecf2',
    align: 'center',
    maxWidthPx: 1.2,
  });
  badgeText.position.set(0.65, 0.5, 0.01); // top‑right corner above card
  group.add(badgeText);

  // --- Load texture asynchronously ---
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  // --- Handlers ---
  const hoverTween = { current: null };

  const handlers = {
    hoverEnter: () => {
      // Lift card + show border
      if (hoverTween.current) hoverTween.current.kill();
      hoverTween.current = gsap.to(cardMesh.position, {
        y: 0.15,
        duration: 0.4,
        ease: 'power2.out',
      });
      gsap.to(borderMat, {
        opacity: 1,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    hoverExit: () => {
      if (hoverTween.current) hoverTween.current.kill();
      hoverTween.current = gsap.to(cardMesh.position, {
        y: 0,
        duration: 0.4,
        ease: 'power2.out',
      });
      gsap.to(borderMat, {
        opacity: 0,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    click: () => {
      // Press‑down animation + emit
      gsap.to(cardMesh.scale, {
        duration: 0.12,
        scale: 0.97,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(cardMesh.scale, {
            duration: 0.2,
            scale: 1,
            ease: 'power4.out',
          });
          ctx.emit('hub-journal.select', {});
        },
      });
    },
  };

  // --- Cleanup ---
  const cleanup = () => {
    if (hoverTween.current) hoverTween.current.kill();
    gsap.killTweensOf(cardMesh.position);
    gsap.killTweensOf(cardMesh.scale);
    gsap.killTweensOf(borderMat);
    cardGeo.dispose();
    cardMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    // Dispose text children (created by fontAtlas internally disposes geometries)
    badgeText.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  // --- Expose internals for data binding ---
  group.userData.handlers = handlers;
  group.userData.cleanup = cleanup;
  group.userData.stockBadge = badgeText; // target for trpc.inventory.status.inStock

  return group;
}
